$blocks = @(
    New-ImageMetricCard -Label Requests -Value 12840 -Format N0 -Trend '+12% this week' -Caption 'Completed API requests' -Status Positive -MiniValues 8200, 9400, 10100, 12840 -Width 336 -Height 176 -Theme Dark
    New-ImageListBlock -Title Checks -Item API, Database, Queue -Value Healthy, Warning, Healthy -Status Positive, Warning, Positive -Theme Dark
    New-ImageTableBlock -Title Services -Column Name, Status -StatusColumn Status -Row @(
        @{ Name = 'API'; Status = 'Healthy' }
        @{ Name = 'Database'; Status = 'Warning' }
        @{ Name = 'Queue'; Status = 'Healthy' }
    ) -Theme Dark
)

$wide = New-ImageVisualGrid -Title 'Service health' -Subtitle 'Last refresh 14:24 UTC' -Columns 2 -Gap 16 -Padding 24 -AdaptiveRowHeights -Theme Dark -Content $blocks
$wide | New-ImageVisualStory -FilePath service-health-dark.png

$projects = @(
    [pscustomobject]@{ Project = 'ChartForgeX'; Stack = '.NET'; Status = 'ready' }
    [pscustomobject]@{ Project = 'ImagePlayground'; Stack = 'PowerShell'; Status = 'ready' }
)

$story = New-ImageConsoleStory -Title 'pwsh - OpenSource' -WorkingDirectory OpenSource -Theme Dark -WindowStyle WindowsTerminal -Width 640 -Content {
    New-ImageConsoleStoryCommand -Text 'Get-ActivePortfolio'
    $projects | New-ImageConsoleStoryTable -Property Project, Stack, Status -Header PROJECT, STACK, STATUS
    New-ImageConsoleStoryBlankLine
    New-ImageConsoleStoryCommand -Text './build.ps1'
    New-ImageConsoleStoryOutput -Text 'PASS  all checks' -Style Success
}
$story | Export-ImageConsoleStory -Path powershell-console-story-dark.gif -FramesPerSecond 8 -EndHoldSeconds 1.5
